import sys
from collections import deque, defaultdict

def find_centroid(n, adj):
    def bfs_size(node, parent):
        queue = deque([node])
        size = {node: 1}
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v != parent:
                    size[v] = size[u] + 1
                    queue.append(v)
                    parent[v] = u
        return size

    def find_centroid(node, parent, total_size):
        queue = deque([node])
        while queue:
            u = queue.popleft()
            is_centroid = True
            for v in adj[u]:
                if v != parent:
                    if size[v] > total_size // 2:
                        is_centroid = False
                        queue.append(v)
            if is_centroid and (total_size - size[u]) <= total_size // 2:
                return u
            for v in adj[u]:
                if v != parent:
                    queue.append(v)

    parent = {1: -1}
    size = bfs_size(1, parent)
    return find_centroid(1, parent, n)

def bfs_min_time(start, adj, attacked_cities):
    queue = deque([(start, 0)])
    visited = {start}
    max_time = 0
    while queue:
        u, time = queue.popleft()
        if u in attacked_cities:
            max_time = max(max_time, time)
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                queue.append((v, time + 1))
    return max_time

def solve():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    adj = defaultdict(list)
    index = 2
    for _ in range(n - 1):
        u = int(data[index])
        v = int(data[index + 1])
        adj[u].append(v)
        adj[v].append(u)
        index += 2

    attacked_cities = set(map(int, data[index:index + m]))

    centroid = find_centroid(n, adj)

    min_time = bfs_min_time(centroid, adj, attacked_cities)

    print(centroid)
    print(min_time)
